def count_returnable_rooms(n, s):
    visited = [False] * n
    returnable_count = 0

    for start in range(n):
        if visited[start]:
            continue

        current = start
        cycle_length = 0

        while not visited[current]:
            visited[current] = True
            cycle_length += 1

            if s[current] == '>':
                current = (current + 1) % n
            elif s[current] == '<':
                current = (current - 1) % n
            else:
                # If the belt is off, we can move in either direction
                # We need to check both directions
                next1 = (current + 1) % n
                next2 = (current - 1) % n

                if not visited[next1]:
                    current = next1
                elif not visited[next2]:
                    current = next2
                else:
                    break

        # Any cycle allows the snake to return to its original room
        if cycle_length > 0:
            returnable_count += cycle_length

    return returnable_count

