import sys

def count_returnable_rooms(t, test_cases):
    results = []
    for n, s in test_cases:
        visited = [False] * n
        returnable = [False] * n

        for start in range(n):
            if visited[start]:
                continue

            current = start
            path = []
            while not visited[current]:
                visited[current] = True
                path.append(current)
                if s[current] == '>':
                    current = (current + 1) % n
                elif s[current] == '<':
                    current = (current - 1) % n
                else:
                    # Try both directions
                    next1 = (current + 1) % n
                    next2 = (current - 1) % n
                    if not visited[next1]:
                        current = next1
                    elif not visited[next2]:
                        current = next2
                    else:
                        break

            # Check if the path forms a cycle
            if current in path:
                cycle_start = path.index(current)
                for i in range(cycle_start, len(path)):
                    returnable[path[i]] = True

        results.append(sum(returnable))

    return results

